function getHindiMonth($m) {
    $months = [
        1 => "जनवरी", 2 => "फ़रवरी", 3 => "मार्च", 4 => "अप्रैल",
        5 => "मई", 6 => "जून", 7 => "जुलाई", 8 => "अगस्त",
        9 => "सितम्बर", 10 => "अक्टूबर", 11 => "नवम्बर", 12 => "दिसम्बर"
    ];
    return isset($months[$m]) ? $months[$m] : "";
}

